import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import java.nio.file.*;import java.util.*;
class Isolate{public static void main(String[]args)throws Exception{ClassNode c=new ClassNode();new ClassReader(Files.readAllBytes(Paths.get(args[0]))).accept(c,0);c.methods.removeIf(m->!Arrays.asList("chunkPopulated","mix","cityTerrain","filterSite","<clinit>","<init>").contains(m.name));for(MethodNode m:c.methods){if(m.name.equals("cityTerrain"))m.access=Opcodes.ACC_STATIC|Opcodes.ACC_PUBLIC;for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode){MethodInsnNode k=(MethodInsnNode)i;if(k.owner.equals(c.name)&&Arrays.asList("data","candidateBiome").contains(k.name))k.owner="org/sonicraft/backport/Fixture";}}ClassWriter w=new ClassWriter(0);c.accept(w);Files.write(Paths.get(args[1]),w.toByteArray());}}
